import copy
import pytest
from fabops.domain import run


def test_future_version_retains_known_support():
    request = {'samples': [{'id': 'p0', 'channel': 'pressure', 't': '0', 'raw': '600', 'revision': 1, 'recorded': 0, 'epoch': 'e', 'valid': True, 'deleted': False}, {'id': 'p2', 'channel': 'pressure', 't': '2', 'raw': '600', 'revision': 1, 'recorded': 0, 'epoch': 'e', 'valid': True, 'deleted': False}, {'id': 'q0', 'channel': 'flow', 't': '0', 'raw': '60', 'revision': 1, 'recorded': 0, 'epoch': 'e', 'valid': True, 'deleted': False}, {'id': 'q2', 'channel': 'flow', 't': '2', 'raw': '60', 'revision': 1, 'recorded': 0, 'epoch': 'e', 'valid': True, 'deleted': False}, {'id': 'p2', 'channel': 'pressure', 't': '2', 'raw': '1200', 'revision': 2, 'recorded': 8, 'epoch': 'e', 'valid': True, 'deleted': False}], 'calibrations': [{'id': 'pressure', 'channel': 'pressure', 'start': '-100', 'end': '100', 'gain': '1', 'offset': '0', 'revision': 1, 'recorded': 0, 'deleted': False}, {'id': 'flow', 'channel': 'flow', 'start': '-100', 'end': '100', 'gain': '1', 'offset': '0', 'revision': 1, 'recorded': 0, 'deleted': False}], 'clocks': [{'channel': 'pressure', 'epoch': 'e', 'local_origin': '0', 'global_origin': '0', 'rate': '1'}, {'channel': 'flow', 'epoch': 'e', 'local_origin': '0', 'global_origin': '0', 'rate': '1'}], 'windows': [{'id': 'w', 'start': '0', 'end': '2'}], 'queries': [1], 'max_gap': {'pressure': '3', 'flow': '3'}, 'min_coverage': '1'}
    before = copy.deepcopy(request)
    assert run(request) == [{'windows': [{'id': 'w', 'coverage': '1', 'accepted': True, 'volume': '2', 'work': '120'}], 'changes': [{'op': 'upsert', 'value': {'id': 'w', 'coverage': '1', 'accepted': True, 'volume': '2', 'work': '120'}}]}]
    assert request == before

